import java.util.*;

class Solution {
    public int lowestCommonAncestor(TreeNode root, int p, int q) {
        return find(root, p, q).val;
    }

    private TreeNode find(TreeNode n, int p, int q) {
        if (n == null || n.val == p || n.val == q) return n;
        TreeNode a = find(n.left, p, q);
        TreeNode b = find(n.right, p, q);
        if (a != null && b != null) return n;  // p and q are on different sides
        return a != null ? a : b;
    }
}

