class Solution:
    def lowestCommonAncestor(self, root: Optional[TreeNode], p: int, q: int) -> int:
        def go(n):
            if not n or n.val in (p, q): return n
            a, b = go(n.left), go(n.right)
            return n if a and b else a or b
        return go(root).val

