function lowestCommonAncestor(root, p, q) {
  const par = new Map([[root.val, null]]); const st = [root];
  while (st.length) { const n = st.pop(); for (const c of [n.left, n.right]) if (c) { par.set(c.val, n.val); st.push(c); } }
  const anc = new Set(); for (let x = p; x !== null; x = par.get(x)) anc.add(x);
  let y = q; while (!anc.has(y)) y = par.get(y);
  return y;
}
